data: {"toolCallId":"batch_write-1785381971496","toolName":"batch_write","state":"result","args":{"files":[{"path":"index.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
